WITH enriched AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, LAG(amount, 1) OVER (ORDER BY amount, id) AS prev_amount, LAST_VALUE(shipping_fee) IGNORE NULLS OVER (PARTITION BY channel, store_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_shipping_fee FROM orders) SELECT id, customer_id, store_id, status, amount, discount, shipping_fee, last_known_shipping_fee, CASE WHEN status RLIKE '^(RETURNED|PENDING)$' THEN 'PRIORITY' ELSE 'CORE' END AS status_zone FROM enriched
